export function noWhitespace(control: AbstractControl) {
  return control.value?.trim() ? null : { whitespace: true };
}

export const uniqueName: AsyncValidatorFn = (control) =>
  inject(UserService).exists(control.value).pipe(
    map((taken) => (taken ? { taken: true } : null)),
  );

export const passwordsMatch: ValidatorFn = (group) => {
  const p = group.get('password')?.value;
  const c = group.get('confirm')?.value;
  return p === c ? null : { mismatch: true };
};

